import {useLayoutEffect,useMemo,useRef} from 'react';
import {FlatList,Platform,Text,View,useWindowDimensions,type ViewProps} from 'react-native';
import {createStore} from 'zustand/vanilla';
import {useStore} from 'zustand';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
export interface OutlineNode {id:string;parentId:string|null;label:string;description?:string;disabledReason?:string}
export interface OutlineTreeProps extends Omit<ViewProps,'children'>,ScopedControlProps {
 label:string;nodes:readonly OutlineNode[];selectedId:string|null;expandedIds?:readonly string[];
 onSelect:(id:string,signal?:AbortSignal)=>unknown;onExpandedChange?:(ids:readonly string[])=>void;viewportHeight?:number;unstyled?:boolean;
}
function indexTree(nodes:readonly OutlineNode[]){
 if(nodes.length>100000||new Set(nodes.map(n=>n.id)).size!==nodes.length||nodes.some(n=>!n.id.trim()||n.id.length>256||!n.label.trim()||n.label.length>4096||(n.description?.length??0)>8192))throw new RangeError('Invalid outline nodes');
 const byId=new Map(nodes.map(n=>[n.id,n])),children=new Map<string|null,OutlineNode[]>(),depths=new Map<string,number>();
 for(const n of nodes){if(n.parentId!==null&&!byId.has(n.parentId))throw new RangeError('Outline parent unavailable');const list=children.get(n.parentId)??[];list.push(n);children.set(n.parentId,list);}
 for(const n of nodes){const trail:OutlineNode[]=[],seen=new Set<string>();let at:OutlineNode|undefined=n;while(at&&!depths.has(at.id)){if(seen.has(at.id))throw new RangeError('Outline hierarchy cycle');seen.add(at.id);trail.push(at);at=at.parentId===null?undefined:byId.get(at.parentId);}let depth=at?depths.get(at.id)!:0;for(const node of trail.reverse()){depth++;if(depth>256)throw new RangeError('Outline hierarchy exceeds supported depth');depths.set(node.id,depth);}}
 return {byId,children,depths};
}
/** Shared virtual tree owner for bookmarks, component/frame trees and hierarchical navigation. */
export function OutlineTree({scope='outline-tree',revision=0,...props}:OutlineTreeProps){
 const {label,nodes,selectedId,expandedIds,onSelect:_select,onExpandedChange:_expand,viewportHeight=420,unstyled=false,disabledReason,style,...rest}=props;
 const tree=useMemo(()=>indexTree(nodes),[nodes]);if(!label.trim()||!Number.isFinite(viewportHeight)||viewportHeight<44||viewportHeight>8192)throw new RangeError('Invalid outline viewport');
 const identity=JSON.stringify(controlIdentity(scope,revision)),owner=JSON.stringify([identity,disabledReason]),guard=useScopedControl(owner,props,disabledReason!==undefined),off=guard.pending||disabledReason!==undefined;
 const local=useRef<ReturnType<typeof makeStore>|null>(null);local.current??=makeStore();const store=local.current,localExpanded=useStore(store,s=>s.expanded),expanded=useMemo(()=>new Set(expandedIds??localExpanded),[expandedIds,localExpanded]);
 useLayoutEffect(()=>{if(expandedIds===undefined)store.setState({expanded:new Set()});},[identity]);
 useLayoutEffect(()=>{if(expandedIds!==undefined||!selectedId)return;const next=new Set(store.getState().expanded);let at=tree.byId.get(selectedId);while(at?.parentId){next.add(at.parentId);at=tree.byId.get(at.parentId);}store.setState({expanded:next});},[selectedId,tree,owner]);
 const rows:OutlineNode[]=[];const pending=[...(tree.children.get(null)??[])].reverse();while(pending.length){const n=pending.pop()!;rows.push(n);if(expanded.has(n.id)){const children=tree.children.get(n.id)??[];for(let i=children.length-1;i>=0;i--)pending.push(children[i]!);}}
 const {fontScale}=useWindowDimensions(),rowHeight=Math.max(44,Math.ceil(fontScale*20)+16),list=useRef<FlatList<OutlineNode>|null>(null),refs=useRef(new Map<string,{focus?:()=>void}>()),focusAfterScroll=useRef<string|null>(null);
 const toggle=(id:string)=>{const h=guard.current();if(!h)return;const next=new Set(h.expandedIds??store.getState().expanded);if(next.has(id))next.delete(id);else next.add(id);if(h.expandedIds===undefined)store.setState({expanded:next});h.onExpandedChange?.([...next]);};
 return <View {...rest} style={[{gap:6,minWidth:0},style]} accessibilityLabel={label} {...(Platform.OS==='web'?{role:'tree' as const}:{})}><FlatList ref={list} data={rows} keyExtractor={n=>n.id} style={{height:viewportHeight}} initialNumToRender={10} windowSize={5} getItemLayout={(_d,index)=>({index,length:rowHeight,offset:index*rowHeight})} extraData={[expanded,selectedId,off]} ListEmptyComponent={<Text {...{className:unstyled?undefined:'text-text'}}>No outline entries supplied</Text>} renderItem={({item,index})=>{const children=tree.children.get(item.id)??[],open=expanded.has(item.id),disabled=off||item.disabledReason!==undefined;return <View style={{height:rowHeight,flexDirection:'row',alignItems:'center',paddingStart:Math.min(12,(tree.depths.get(item.id)??1)-1)*12,gap:4}}>{children.length?<Button title={open?'−':'+'} accessibilityLabel={(open?'Collapse ':'Expand ')+item.label} accessibilityState={{expanded:open}} variant="ghost" disabled={disabled} unstyled={unstyled} onPress={()=>toggle(item.id)}/>:<View style={{width:44}}/>}<View style={{flex:1,minWidth:0}}><Button numberOfLines={1} ref={node=>{if(node){refs.current.set(item.id,node as unknown as {focus?:()=>void});if(focusAfterScroll.current===item.id){(node as unknown as {focus?:()=>void}).focus?.();focusAfterScroll.current=null;}}else refs.current.delete(item.id);}} title={item.label} accessibilityLabel={item.label+(item.description?', '+item.description:'')} accessibilityHint={item.disabledReason} accessibilityState={{selected:item.id===selectedId,...(children.length?{expanded:open}:{})}} disabled={disabled} variant="ghost" unstyled={unstyled} onPress={()=>guard.run('select',(h,s)=>h.nodes.some(n=>n.id===item.id&&n.disabledReason===undefined)?h.onSelect(item.id,s):undefined)} onKeyDown={e=>{if(disabled)return;const key=e.nativeEvent.key;let target:number|undefined;if(key==='ArrowDown')target=Math.min(rows.length-1,index+1);else if(key==='ArrowUp')target=Math.max(0,index-1);else if(key==='Home')target=0;else if(key==='End')target=rows.length-1;else if(key==='ArrowRight'&&children.length&&!open)toggle(item.id);else if(key==='ArrowLeft'&&open)toggle(item.id);else if(key==='ArrowLeft'&&item.parentId!==null)target=rows.findIndex(n=>n.id===item.parentId);else if(key==='ArrowRight'&&open&&children.length)target=index+1;else return;e.preventDefault?.();if(target!==undefined&&target>=0){const id=rows[target]!.id,node=refs.current.get(id);if(node)node.focus?.();else{focusAfterScroll.current=id;list.current?.scrollToOffset({offset:target*rowHeight,animated:false});}}}}/></View></View>;}}/><ErrorMessage message={guard.error??disabledReason} unstyled={unstyled}/></View>;
}
function makeStore(){return createStore(()=>({expanded:new Set<string>()}));}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}
